func children(_ el: AXUIElement) -> [AXUIElement] {
    (attr(el, kAXChildrenAttribute) as? [AXUIElement]) ?? []
}
func dumpTree(_ el: AXUIElement, indent: String = "", depth: Int = 0) {
    if depth > 6 { return }
    let role = attr(el, kAXRoleAttribute) as? String ?? "?"
    let name = attr(el, kAXTitleAttribute) as? String ?? attr(el, kAXDescriptionAttribute) as? String ?? ""
    var pos: AnyObject?; AXUIElementCopyAttributeValue(el, kAXPositionAttribute, &pos)
    var size: AnyObject?; AXUIElementCopyAttributeValue(el, kAXSizeAttribute, &size)
    var p = CGPoint.zero; var s = CGSize.zero
    if let pos { AXValueGetValue(pos as! AXValue, .cgPoint, &p) }
    if let size { AXValueGetValue(size as! AXValue, .cgSize, &s) }
    if !name.isEmpty || role == "AXButton" || role == "AXWindow" || role == "AXMenuItem" || role == "AXStaticText" {
        print("\(indent)\(role) '\(name)' pos=\(Int(p.x)),\(Int(p.y)) size=\(Int(s.width))x\(Int(s.height))")
    }
    for c in children(el) { dumpTree(c, indent: indent + "  ", depth: depth + 1) }
}

if cmd == "list" {
    dumpTree(app)
} else if cmd == "move", args.count >= 5, let x = Double(args[3]), let y = Double(args[4]) {
    let wins = (attr(app, kAXWindowsAttribute) as? [AXUIElement]) ?? []
    print("windowCount=\(wins.count)")
    for (i, w) in wins.enumerated() {
        let title = attr(w, kAXTitleAttribute) as? String ?? ""
        var pos = CGPoint(x: x, y: y)
        let v = AXValueCreate(.cgPoint, &pos)!
        let err = AXUIElementSetAttributeValue(w, kAXPositionAttribute, v)
        print("moved[\(i)] '\(title)' err=\(err.rawValue) -> \(x),\(y)")
    }
} else if cmd == "click", args.count >= 5, let x = Double(args[3]), let y = Double(args[4]) {
    let src = CGEventSource(stateID: .hidSystemState)
    let down = CGEvent(mouseEventSource: src, mouseType: .leftMouseDown, mouseCursorPosition: CGPoint(x: x, y: y), mouseButton: .left)!
    let up = CGEvent(mouseEventSource: src, mouseType: .leftMouseUp, mouseCursorPosition: CGPoint(x: x, y: y), mouseButton: .left)!
    down.post(tap: .cghidEventTap)
    usleep(80_000)
    up.post(tap: .cghidEventTap)
    print("clicked \(x),\(y)")
} else if cmd == "press", args.count >= 4 {
    let want = args[3]
    func walk(_ el: AXUIElement) -> AXUIElement? {
        let name = (attr(el, kAXTitleAttribute) as? String) ?? (attr(el, kAXDescriptionAttribute) as? String) ?? ""
        if name == want { return el }
        for c in children(el) { if let f = walk(c) { return f } }
        return nil
    }
    guard let el = walk(app) else { fputs("not found: \(want)\n", stderr); exit(1) }
    AXUIElementPerformAction(el, kAXPressAction as CFString)
    print("pressed \(want)")
} else {
    fputs("bad command\n", stderr)
    exit(2)
}
